package app

// Run starts the server.
func Run() {
	println("listening")
}

// Serve handles a single request.
func Serve(req string) string {
	return "ok: " + req
}

package app

// TitleCase uppercases the first letter of s.
func TitleCase(s string) string {
	if s == "" {
		return s
	}
	return string([]rune(s)[0]) + s[1:]
}
